const storyConcepts=new Map(storyCatalog.concepts.map(c=>[c.id,c]));
const storyIndex=new Map();for(const r of storyCatalog.records)for(const title of r.lookupTitles)if(title)storyIndex.set(N(title)+'|'+N(r.author),r);
function attachStoryFacts(book,title,author){
 const r=storyIndex.get(N(title)+'|'+N(author));if(!r)return book;
 book.storyFacts=r.facts.map(f=>({...f,label:storyConcepts.get(f.concept).label,category:storyConcepts.get(f.concept).category}));
 book.storyReview={checked:r.checked,version:storyCatalog.version,outcome:r.reviewOutcome,limitations:r.limitations};
 if(r.newSourceCheck){book.blurb=r.basis;book.searchDescription=r.basis;book.sources=[...new Set([...(book.sources||[]),...r.sources])];book.verification.fields.blurb={value:r.basis,status:'supported-summary',rationale:'Book-specific author/publisher premise paraphrased on '+r.checked+'. This is not an exhaustive plot audit.',evidence:r.sources};book.fieldSources||={};book.fieldSources.blurb=r.sources;}
 // Only a small set of reusable concepts joins the existing filter categories.
 for(const fact of book.storyFacts){const field=storyConcepts.get(fact.concept).filterField;if(!field)continue;book[field]=[...new Set([...(book[field]||[]),fact.label])];}
 book.verification.fields.story_connections={value:book.storyFacts.length?book.storyFacts.map(f=>f.label+' — '+f.subject+' → '+f.object):'No additional connection established',status:book.storyFacts.length?'supported-summary':'unknown',rationale:r.basis+' '+r.limitations,evidence:r.sources};
 // Per-concept provenance is retained separately from the general synopsis and mood judgments.
 for(const field of new Set(book.storyFacts.map(f=>storyConcepts.get(f.concept).filterField).filter(Boolean))){const previous=book.verification.fields[field]||{};book.verification.fields[field]={...previous,value:book[field],status:'supported-summary',rationale:(previous.rationale||'')+' Additional premise labels are documented in Story connections.',evidence:[...new Set([...(previous.evidence||[]),...book.storyFacts.filter(f=>storyConcepts.get(f.concept).filterField===field).flatMap(f=>f.sources)])]};}
 return book;
}

